def max_nonadjacent(nums):
    previous, current = 0, 0
    for value in nums:
        previous, current = current, max(current, previous + value)
    return current

solution.java:
class Solution {
    public long maxNonadjacent(int[] nums) {
        long previous = 0, current = 0;
        for (int value : nums) {
            long next = Math.max(current, previous + value);
            previous = current;
            current = next;
        }
        return current;
    }
}

